    if (size <= 0) {
        return;
    }
    if (this.buffer == null) {
        this.buffer = new byte[size];
    }
    int oldLength = this.length;
    boolean success = false;
    try {
        System.arraycopy(this.buffer, 0, this.buffer, size, oldLength);
