@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Get the number of vertices and edges in the graph
    int numVertices = target.getNumVertices();
    int numEdges = target.getNumEdges();

    // Create a map to store the vertices in the bipartite graph
    Map<String,V> vertexMap = new HashMap<>();

    // Create a map to store the edges in the bipartite graph
    Map<String,E> edgeMap = new HashMap<>();

    // Generate the vertices and edges of the bipartite graph
    for (int i = 1; i <= numVertices; i++) {
        V vertex = target.getVertex(i);
        vertexMap.put(vertex.getName(), vertex);
        for (int j = 1; j <= numEdges; j++) {
            E edge = target.getEdge(j);
            edgeMap.put(edge.getSourceName() + "_" + edge.getTargetName(), edge);
            for (int k = 1; k <= numVertices; k++) {
                V otherVertex = target.getVertex(k);
                if (!vertex.getName().equals(otherVertex.getName())) {
                    E newEdge = new Edge(vertex.getName(), otherVertex.getName());
                    edgeMap.put(newEdge.getSourceName() + "_" + newEdge.getTargetName(), newEdge);
                }
            }
        }
    }

    // Create the complete bipartite graph
    Graph<V,E> completeGraph = new Graph<>(vertexMap, edgeMap);

    // Set the graph attributes
    completeGraph.setVertexCount(numVertices);
    completeGraph.setEdgeCount(numEdges);

    // Return the complete bipartite graph
    return completeGraph;
}

