        cache.put(data.getKey(), mergedValues);
    } finally {
        // Unlock the cache
        lock.unlock();
    }
}

@Override
public void accept(final METRICS data) {
    if (data == null || data.getMetrics() == null) {
        return;
    }
    List<Metric> existingMetrics = this.getExtendedCache().get(data.getId());
    if (existingMetrics == null) {
        existingMetrics = new ArrayList<>();
        this.getExtendedCache().put(data.getId(), existingMetrics);
    }
    List<Metric> mergedMetrics = new ArrayList<>();
    for (Metric metric : data.getMetrics()) {
        Metric existingMetric = findMetric(metric.getId(), existingMetrics);
        if (existingMetric == null) {
            mergedMetrics.add(metric);
        } else {
            Metric updatedMetric = updateMetric(existingMetric, metric);
            mergedMetrics.add(updatedMetric);
        }
    }
    this.getExtendedCache().put(data.getId(), mergedMetrics);
}

private Metric findMetric(String id, List<Metric> metrics) {
    for (Metric metric : metrics) {
        if (id.equals(metric.getId())) {
            return metric;
        }
    }
    return null;
}

private Metric updateMetric(Metric existingMetric, Metric newMetric) {
    existingMetric.setValue(newMetric.getValue());
    existingMetric.setTimestamp(newMetric.getTimestamp());
    return existingMetric;
}

