}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Step 1: Convert the input mappings to a Map
    Map<String, Object> inputMap = new HashMap<>();
    for (Map.Entry<String, Object> entry : mappings.entrySet()) {
        String fieldName = entry.getKey();
        Object fieldValue = entry.getValue();
        inputMap.put(fieldName, fieldValue);
    }

    // Step 2: Get the current mappings for the given table name
    Map<String, Object> currentMappings = getCurrentMappings(tableName);

    // Step 3: Find the differences between the input mappings and the current mappings
    Map<String, Object> diffMap = new HashMap<>();
    for (Map.Entry<String, Object> entry : currentMappings.entrySet()) {
        String fieldName = entry.getKey();
        Object currentFieldValue = entry.getValue();
        Object inputFieldValue = inputMap.get(fieldName);
        if (!currentFieldValue.equals(inputFieldValue)) {
            diffMap.put(fieldName, inputFieldValue);
        }
    }

    // Step 4: Create a new Mappings object with the differences
    Mappings diffMappings = new Mappings();
    for (Map.Entry<String, Object> entry : diffMap.entrySet()) {
        String fieldName = entry.getKey();
        Object fieldValue = entry.getValue();
        diffMappings.addField(fieldName, fieldValue);
    }

    // Step 5: Return the diffMappings
    return diffMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    Mappings currentMappings = getCurrentMappings(tableName);
    Map<String, Object> diffMap = new HashMap<>();
    for (Map.Entry<String, Object> entry : currentMappings.entrySet()) {
        if (!mappings.containsKey(entry.getKey())) {
            diffMap.put(entry.getKey(), entry.getValue());
        }
    }
    return diffMap;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Get the current structure of the table
    Mappings currentMappings = getCurrentStructure(tableName);

    // Remove any fields that exist in the current structure
    for (Field field : mappings.getFields()) {
        if (currentMappings.getField(field.getName()) != null) {
            mappings.removeField(field.getName());
        }
    }

    // Return the modified mappings
    return mappings;
}

private Mappings getCurrentStructure(String tableName) {
    // Get the mapping API endpoint URL
    String endpointUrl = ClusterClient.endpointUrl(
            "GET /_mappings/{tableName}",
            "{index}",
            tableName);

    // Make a GET request to the API endpoint
    HttpResponse response = this.httpClient.execute(new HttpGet(endpointUrl));

    // Parse the response as a JSON object
    JsonNode responseJson = this.objectMapper.readTree(response.getEntity().getContent());

    // Extract the mappings from the response
    Mappings currentMappings = new Mappings(responseJson);

    return currentMappings;
}

