public static long compressTimeBucket(long timeBucket, int dayStep) {
    int month = (int) ((timeBucket) % 100);
    int day = (int) (((timeBucket) / 100) % 100);
    int year = (int) (timeBucket / 10000);

    if (day % dayStep == 0) {
        day = (day / dayStep) * dayStep + 1;
    } else {
        day = (day / dayStep) * dayStep + dayStep;
    }

    if (day == 0) {
        month--;
    }

    return year * 10000 + month * 100 + day;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
  long reFormattedTimeBucket = timeBucket;
  if (dayStep > 0 && dayStep < 32) {
    int day = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    if (day > dayStep) {
     day = day - (day % dayStep);
    }

    reFormattedTimeBucket = year * 10000 + month * 100 + day;
  }
  return reFormattedTimeBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep == 1 || dayStep == 5 || dayStep == 10) {
        return timeBucket;
    }
    int dayOfMonth = (int) (timeBucket % 100);
    int dayOfMonthAligned = (int) (timeBucket % 100 / dayStep) * dayStep + 1;
    if (dayOfMonthAligned > dayOfMonth) {
        dayOfMonthAligned -= dayStep;
    }
    long timeBucketAligned = timeBucket - dayOfMonth + dayOfMonthAligned;
    return timeBucketAligned;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    long reFormattedTimeBucket = timeBucket - (timeBucket % (dayStep * 86400000L));
    return reFormattedTimeBucket;
}

