public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Enlarge the byte vector if necessary
    if (byteLength > byteArrayValue.length - byteOffset) {
        byte[] newArray = new byte[byteOffset + byteLength];
        System.arraycopy(byteArrayValue, 0, newArray, 0, byteArrayValue.length);
        byteArrayValue = newArray;
    }
    // Copy the bytes from byteArrayValue to this byte vector
    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
        this.data[i] = byteArrayValue[i];
    }
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        if (byteOffset < 0 || byteLength < 0) {
            throw new IllegalArgumentException("byteOffset and byteLength must be non-negative");
        }
        int newSize = this.length + byteLength;
        if (newSize > this.data.length) {
            resize(newSize);
        }
        System.arraycopy(this.data, 0, this.data, byteLength, this.length - byteLength);
        this.length = newSize;
    } else {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new ArrayIndexOutOfBoundsException("byteOffset out of range");
        }
        int newSize = this.length + byteLength;
        if (newSize > this.data.length) {
            resize(newSize);
        }
        System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
        this.length = newSize;
    }
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("Invalid byte offset or length");
        }
        ensureCapacity(byteLength);
        System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
        this.length += byteLength;
    } else {
        if (byteLength < 0) {
            throw new IndexOutOfBoundsException("Invalid byte length");
        }
        ensureCapacity(byteLength);
        Arrays.fill(this.data, this.length, this.length + byteLength, (byte) 0);
        this.length += byteLength;
    }
    return this;
}

