    final int strLen = str.length();
    if (strLen == 0) {
        return lb;
    }
    final int start = lb.position();
    final int end = start + strLen;
    final byte[] buffer = lb.buffer();
    int i = start;
    for (int j = 0; j < strLen; j++) {
        char c = str.charAt(j);
        if (c < 0x80) {
            buffer[i++] = (byte) c;
        } else if (c < 0x800) {
            buffer[i++] = (byte) (0xC0 | (c >> 6));
            buffer[i++] = (byte) (0x80 | (c & 0x3F));
        } else if (Character.isSurrogate(c)) {
            char low = str.charAt(j++);
            if (!Character.isSurrogatePair(c, low)) {
                throw new IllegalArgumentException("Invalid surrogate pair");
            }
            int codePoint = Character.toCodePoint(c, low);
            buffer[i++] = (byte) (0xF0 | (codePoint >> 18));
            buffer[i++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
            buffer[i++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            buffer[i++] = (byte) (0x80 | (codePoint & 0x3F));
        } else {
            buffer[i++] = (byte) (0xE0 | (c >> 12));
            buffer[i++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            buffer[i++] = (byte) (0x80 | (c & 0x3F));

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Check if the string is null or empty
    if (str == null || str.length() == 0) {
        return lb;
    }

    // Convert the string to UTF-8 bytes
    byte[] bytes = str.toString().getBytes(StandardCharsets.UTF_8);

    // Write the bytes to the LinkedBuffer
    for (byte b : bytes) {
        lb.write(b);
    }

    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    byte[] bytes = str.getBytes(StandardCharsets.UTF_8);
    int length = bytes.length;
    ByteBuffer buffer = lb.getBuffer(length);
    buffer.put(bytes);
    lb.setAvailableSize(lb.getAvailableSize() - length);
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    /*
     * Implementation of the writeUTF8 method
     */
    // Write the length of the string as a 32-bit integer
    int length = str.length();
    lb.putInt(length);

    // Write the string as UTF-8 bytes
    for (int i = 0; i < length; i++) {
        int c = str.charAt(i);
        if (c <= 0x007F) {
            // 1-byte UTF-8 encoding
            lb.put((byte) c);
        } else if (c <= 0x07FF) {
            // 2-byte UTF-8 encoding
            lb.put((byte) (0xC0 | (c >> 6)));
            lb.put((byte) (0x80 | (c & 0x3F)));
        } else {
            // 3-byte UTF-8 encoding
            lb.put((byte) (0xE0 | (c >> 12)));
            lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.put((byte) (0x80 | (c & 0x3F)));
        }
    }

    // Return the linked buffer
    return lb;
}

