public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getPath();
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    int start = 0;
    int end = 0;
    while (end < path.length()) {
        char c = path.charAt(end);
        if (c == '/') {
            String segment = path.substring(start, end);
            if (!segment.isEmpty()) {
                pathSegments.add(new PathSegmentImpl(segment, decode));
            }
            start = end + 1;
        }
        end++;
    }
    if (start < end) {
        String segment = path.substring(start, end);
        if (!segment.isEmpty()) {
            pathSegments.add(new PathSegmentImpl(segment, decode));
        }
    }
    return pathSegments;
}

public class URIUtils {
    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        String path = u.getPath();
        if (path.isEmpty()) {
            return Collections.emptyList();
        }

        // Strip the leading '/' if it is present
        int start = path.charAt(0) == '/' ? 1 : 0;

        // Split the path into segments
        String[] segments = path.substring(start).split("/");

        List<PathSegmentImpl> result = new ArrayList<>(segments.length);
        for (String segment : segments) {
            String decodedSegment = decode ? decodeSegment(segment) : segment;
            result.add(new PathSegmentImpl(decodedSegment, u));
        }
        return result;
    }

    private static String decodeSegment(String segment) {
        // Percent-decode the segment
        String decodedSegment = segment.replace("%2F", "/");
        return decodedSegment;
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
	List<PathSegmentImpl> pathSegments = new ArrayList<>();
	String path = u.getPath();
	if (path.startsWith("/")) {
		path = path.substring(1);
	}
	String[] segments = path.split("/");
	for (String segment : segments) {
		PathSegmentImpl pathSegment = new PathSegmentImpl();
		pathSegment.setName(decode ? URLDecoder.decode(segment, "UTF-8") : segment);
		pathSegments.add(pathSegment);
	}
	return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String[] rawSegments = u.getPath().split("/");
    for (String rawSegment : rawSegments) {
        String segment = decode ? UriUtils.decodePathSegment(rawSegment, CHARSET) : rawSegment;
        PathSegmentImpl pathSegment = new PathSegmentImpl(segment);
        pathSegments.add(pathSegment);
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (path.isEmpty()) {
        return pathSegments;
    }
    int endIndex = path.length();
    if (path.charAt(0) == '/') {
        endIndex = path.indexOf('/', 1);
    }
    while (endIndex != -1) {
        String pathSegment = path.substring(0, endIndex);
        if (decode) {
            pathSegment = URLDecoder.decode(pathSegment, "UTF-8");
        }
        pathSegments.add(new PathSegmentImpl(pathSegment));
        path = path.substring(endIndex + 1);
        if (path.isEmpty()) {
            break;
        }
        endIndex = path.indexOf('/');
    }
    return pathSegments;
}

