public void write(byte[] b, int off, int len) throws IOException {
    if (off < 0 || off > b.length || off + len > b.length) {
        throw new IndexOutOfBoundsException("Invalid offset or length");
    }
    if (len < 1) {
        return;
    }
    int index = 0;
    while (index < len) {
        write(b[off + index]);
        index++;
    }
}

public void write(byte[] b, int off, int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("Data is null");
    }
    if (off < 0 || off >= b.length) {
        throw new IndexOutOfBoundsException("Offset out of bounds");
    }
    if (len < 0 || len > b.length - off) {
        throw new IndexOutOfBoundsException("Length out of bounds");
    }
    if (len == 0) {
        return;
    }
    int totalBytesWritten = 0;
    while (totalBytesWritten < len) {
        int bytesWritten = write(b[off + totalBytesWritten]);
        if (bytesWritten > 0) {
            totalBytesWritten += bytesWritten;
        } else {
            throw new IOException("Failed to write data");
        }
    }
}

