public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double width = box.width();
    double centerX = box.minX() + width / 2;
    Box2D leftBox = box.copy();
    leftBox.setWidth(centerX - box.minX());
    Box2D rightBox = box.copy();
    rightBox.setX(centerX);
    rightBox.setWidth(box.maxX() - centerX);
    return Pair.of(leftBox, rightBox);
}

