public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box){
    // Calculate midpoint of box along x axis
    double midpoint = box.x + (box.width / 2);

    // Create two new boxes with midpoint as divider
    Box2D box1 = new Box2D(box.x, box.y, midpoint - box.x, box.height);
    Box2D box2 = new Box2D(midpoint, box.y, box.x + box.width - midpoint, box.height);

    // Return a pair with the two resulting boxes
    return new Pair<Box2D, Box2D>(box1, box2);
}

