    Box2D leftBox = new Box2D(minX, box.getMinY(), midX, box.getMaxY());
    Box2D rightBox = new Box2D(midX, box.getMinY(), maxX, box.getMaxY());
    return new Pair<>(leftBox, rightBox);
}

