    if (size <= 0) {
        return;
    }
    int newCapacity = Math.max(this.capacity() * 2, size);
    ByteBuffer newBuffer = ByteBuffer.allocate(newCapacity);
    this.array().Position(0);
    newBuffer.write(this.array(), Math.min(this.limit(), this.capacity() - size));
    this.wrap(newBuffer);
}

