	// Step 1: Calculate the new capacity
	int newCapacity = this.size + size;

	// Step 2: Create a new array with the calculated capacity
	byte[] newBytes = new byte[newCapacity];

	// Step 3: Copy the current bytes to the new array
	System.arraycopy(this.bytes, 0, newBytes, 0, this.size);

	// Step 4: Update the bytes field with the new array
	this.bytes = newBytes;
}

