public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        // Write the value of the current node into the output stream
        out.writeInt(node.getValue());
        // Write the size of the current node into the output stream
        out.writeInt(node.getSize());
        // Increment the total size by the size of the current node
        totalSize += node.getSize();
        // Move to the next node in the list
        node = node.getNext();
    }
    return totalSize;
}

