public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 1000) {
        return getPrime(desiredCapacity);
    } else {
        int prime = getPrime(desiredCapacity);
        if (prime - desiredCapacity > desiredCapacity / 10) {
            return prime - 1;
        } else {
            return prime;
        }
    }
}

private static int getPrime(int n) {
    if (n <= 3) {
        return n;
    } else if (n % 2 == 0 || n % 3 == 0) {
        return getPrime(n - 1);
    } else {
        int p = (int) Math.sqrt(n);
        for (int i = 2; i <= p; i++) {
            if (n % i == 0) {
                return getPrime(n - 1);
            }
        }
        return n;
    }
}

