public byte[] toByteArray() {
    // Calculate the total length of all the buffers
    int totalLength = 0;
    for (ByteBuffer buffer : buffers) {
        totalLength += buffer.remaining();
    }

    // Allocate a new byte array to hold all the data
    byte[] data = new byte[totalLength];

    // Copy the data from each buffer into the array
    int offset = 0;
    for (ByteBuffer buffer : buffers) {
        int length = buffer.remaining();
        buffer.get(data, offset, length);
        offset += length;
    }

    return data;
}

public final byte[] toByteArray() {
    // Create a new byte array to hold the contents of all the buffers
    byte[] combinedBytes = new byte[totalSize];
    int offset = 0;

    // Iterate over each buffer and copy its contents to the combined byte array
    for (ByteBuffer buffer : buffers) {
        int bufferSize = buffer.remaining();
        buffer.get(combinedBytes, offset, bufferSize);
        offset += bufferSize;
    }

    return combinedBytes;
}

public final byte[] toByteArray() {
    /* Buffer for storing the data */
    byte[] buffer;

    /* The total size of the data being buffered */
    int totalSize = 0;

    /* Loop through each buffer and add its size to the total */
    for (Buffer b : buffers) {
        totalSize += b.size();
    }

    /* Allocate a new byte array of the total size */
    buffer = new byte[totalSize];

    /* Loop through each buffer and copy its contents to the byte array */
    for (int i = 0; i < buffers.size(); i++) {
        Buffer b = buffers.get(i);
        System.arraycopy(b, 0, buffer, totalSize - i, b.size());
    }

    return buffer;
}

