public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    // Read the CONSTANT_Utf8 entry from the class file
    int utfLength = classFileBuffer.getInt(constantPoolEntryIndex + 3);
    int utfStart = constantPoolEntryIndex + 5;
    for (int i = 0; i < utfLength; i++) {
