public final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
	// Validate input
	if (constantPoolEntryIndex < 0 || constantPoolIndex >= constantPool.size()) {
		throw new IllegalArgumentException("Invalid constant pool index: " + constantPoolEntryIndex);
	}
	if (charBuffer == null || charBuffer.length == 0) {
		throw new IllegalArgumentException("Char buffer must be non-null and non-empty");
	}

	// Read the constant pool entry
	ConstantUtf8Info constantUtf8Info = (ConstantUtf8Info) constantPool.get(constantPoolEntryIndex);
	if (constantUtf8Info == null) {
		throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
	}

	// Get the string from the constant pool entry
	String string = constantUtf8Info.getString();

	// Copy the string to the char buffer
	int stringLength = string.length();
	if (stringLength > charBuffer.length) {
		throw new IllegalArgumentException("Char buffer is not large enough to hold the string");
	}
	string.getChars(0, stringLength, charBuffer, 0);

	return new String(charBuffer);
}

