private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator result = new OuterFaceCirculator(start, dir);
    while (result.hasNext() && !predicate.test(result.getNode())) {
        result.next();
    }
    if (!result.hasNext()) {
        result = new OuterFaceCirculator(stop, dir);
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node currentNode = start;
    while (currentNode != stop) {
        if (predicate.test(currentNode)) {
            return new OuterFaceCirculator(currentNode, start, dir);
        }
        currentNode = dir == OuterFaceCirculator.FORWARD ? currentNode.getNext() : currentNode.getPrevious();
    }
    return new OuterFaceCirculator(stop, start, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);
    Node current = circulator.getCurrent();
    while (current != null && !predicate.test(current)) {
        current = circulator.getNext();
    }
    return new OuterFaceCirculator(current, circulator.getStart(), circulator.getDirection());
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node current = start;
    while (current != stop) {
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current, dir);
        }
        current = current.getConnectedNodes().get(dir);
    }
    return new OuterFaceCirculator(stop, dir);
}

