public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset,final int byteLength) {
    if (byteArrayValue == null) {
        if (byteLength == 0) {
            return this;
        } else {
            throw new IllegalArgumentException("byteLength must be 0 if byteArrayValue is null");
        }
    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset is out of bounds: " + byteOffset);
    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IllegalArgumentException("byteLength is invalid: " + byteLength);
    }
    if (byteOffset == 0 && byteLength == byteArrayValue.length) {
        return putByteArray(byteArrayValue);
    } else {
        byte[] dupByteArray = Arrays.copyOfRange(byteArrayValue, byteOffset, byteOffset + byteLength);
        return putByteArray(dupByteArray);
    }
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Check if byteArrayValue is null
    if (byteArrayValue == null) {
        // If byteArrayValue is null, put byteLength null bytes into this byte vector
        for (int i = 0; i < byteLength; i++) {
            bytes[index++] = 0;
        }
    } else {
        // If byteArrayValue is not null, copy the bytes from byteArrayValue into this byte vector
        for (int i = byteOffset; i < byteOffset + byteLength; i++) {
            bytes[index++] = byteArrayValue[i];
        }
    }
    return this;
}

