    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Invalid byteOffset: " + byteOffset);
    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("Invalid byteLength: " + byteLength);
