public final MatchResult match(CharSequence uri) {
  // Initialize variables
  String[] patternParts = pattern.split("/");
  String[] uriParts = uri.split("/");
  Map<String, String> pathParameters = new HashMap<>();

  // Check if the number of parts match
  if (patternParts.length != uriParts.length) {
    return null;
  }

  // Check if each part matches
  for (int i = 0; i < patternParts.length; i++) {
    if (!patternParts[i].equals(uriParts[i])) {
      // If any part doesn't match, return null
      return null;
    }
  }

  // Check for query parameters
  String queryString = uri.substring(uri.indexOf("?") + 1);
  if (!queryString.isEmpty()) {
    String[] queryParts = queryString.split("&");
    for (String queryPart : queryParts) {
      String[] queryParam = queryPart.split("=");
      if (queryParam.length == 2) {
        pathParameters.put(queryParam[0], queryParam[1]);
      }
    }
  }

  // Return match result
  return new MatchResult(pattern, uri, pathParameters);
}

public final MatchResult match(CharSequence uri) {
    // First, check if the URI is null or empty
    if (uri == null || uri.length() == 0) {
        return null;
    }

    // Next, check if the pattern is null or empty
    if (this.template == null || this.template.length() == 0) {
        return null;
    }

    // Then, check if the format of the URI is incorrect
    if (!uri.contains("://")) {
        return null;
    }

    // At this point, we know the URI is in the correct format, so we can extract the scheme and path
    int schemeSeparator = uri.indexOf("://");
    String scheme = uri.substring(1, schemeSeparator);
    String path = uri.substring(schemeSeparator + 1);

    // Now, we can match the path against the template
    Matcher matcher = this.template.matcher(path);
    if (matcher.matches()) {
        // If the path matches the template, we can extract the URI params
        Map<String, String> params = new HashMap<>();
        int groupCount = matcher.groupCount();
        for (int i = 0; i < groupCount; i++) {
            String paramName = this.params.get(i);
            String paramValue = matcher.group(i);
            params.put(paramName, paramValue);
        }
        return new MatchResult(true, params);
    } else {
        // If the path does not match the template, return a failure result
        return new MatchResult(false, null);
    }
}

