int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 1; i < constantPool.size(); i++) {
        Symbol symbol = constantPool.get(i);
        if (symbol.getName().equals(name) && symbol.getDescriptor().equals(descriptor)) {
            // Return the existing symbol
            return symbol.getIndex();
        }
    }

    // If there's no similar item, add a new ConstantNameAndType symbol
    ConstantNameAndType constantNameAndType = new ConstantNameAndType(name, descriptor);
    constantPool.add(constantNameAndType);
    return constantNameAndType.getIndex();
}

