      return symbol.getIndex();
    }
  }

  // If not found, create a new constant pool entry
  Symbol symbol = new Symbol(Const.CONSTANT_NameAndType, name, descriptor);
  constantPool.add(symbol);
  return symbol.getIndex();
}

