private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    if (node.next == null) {
        node.prev = null;
    } else {
        node.prev.next = node.next;
    }
    if (node.prev != null) {
        node.prev.next = node;
    } else {
        node.prev = null;
    }
    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    // If the node to be unlinked is the last node in the list
    if (node.next == null) {
        // Set the second last node's next pointer to null
        node.prev.next = null;
        // Decrease the list's size
        size--;
        return true;
    } else {
        // If the node to be unlinked is not the last node in the list
        // Set the current node's next pointer to the node after the current node
        node.next.prev = node.prev;
        // Set the previous node's next pointer to the node after the current node
        node.prev.next = node.next;
        // Decrease the list's size
        size--;
        return true;
    }
}

private boolean unlink(ListNodeImpl<E> node) {
    // Check if the given node is not null
    if (node == null) {
        return false;
    }

    // Check if the given node is the head of the list
    if (node == head) {
        // If the given node is the head of the list, remove it
        head = head.next;

        // If the given node is the only node in the list, set the tail to null
        if (head == null) {
            tail = null;
        }

        // Decrease the size of the list
        size--;

        // Return true to indicate that the node was removed
        return true;
    }

    // If the given node is not the head of the list, find the previous node
    ListNodeImpl<E> previous = head;
    while (previous != null && previous.next != node) {
        previous = previous.next;
    }

    // If the given node is not found, return false
    if (previous == null) {
        return false;
    }

    // Set the next node to the node after the given node
    previous.next = node.next;

    // If the given node is the tail of the list, update the tail
    if (tail == node) {
        tail = previous;
    }

    // Decrease the size of the list
    size--;

    // Return true to indicate that the node was removed
    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null || node.next == null) {
        return false;
    }
    ListNodeImpl<E> previous = node.previous;
    if (previous == null) {
        head = node.next;
    } else {
        previous.next = node.next;
    }
    node.next = null;
    node.previous = null;
    node.element = null;
    return true;
}

public boolean unlink(ListNodeImpl<E> node) {
    if (node != null) {
        node.next = null;
        node.prev = null;
        return true;
    }
    return false;
}

