public class SequenceRanges {
  private String sequence;
  private List<Integer> range;
  private int currentIndex;

  public SequenceRanges(String sequence) {
    this.sequence = sequence;
    this.currentIndex = 0;
  }

  public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    while (currentIndex < sequence.length()) {
      int endIndex = findMatchingEnd(currentIndex);
      if (endIndex >= 0) {
        sequenceRanges.add(new SequenceRange(currentIndex, endIndex));
        currentIndex = endIndex + 1;
      }
    }
    return sequenceRanges;
  }

  private int findMatchingEnd(int currentIndex) {
    for (int i = currentIndex + 1; i < sequence.length(); i++) {
      char currentChar = sequence.charAt(currentIndex);
      char previousChar = sequence.charAt(i - 1);
      if (currentChar == '[' || currentChar == ']') {
        if (previousChar == '[' || previousChar == ']') {
          return i - 1;
        }
      }
    }
    return -1;
  }
}

public List<SequenceRange> buildSequenceRanges(List<Profile> profiles, List<Metric> metrics) {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    for (Profile profile : profiles) {
        int profileMetricIndex = 0;
        for (Metric metric : metrics) {
            // Get the current profile's sequence for the current metric
            SequenceRange sequenceRange = profile.getSequenceRange(metric, profileMetricIndex);
            if (sequenceRange != null) {
                // Add the sequence range to the list of sequence ranges
                sequenceRanges.add(sequenceRange);
                profileMetricIndex++;
            }
        }
    }
    return sequenceRanges;
}

