    if (snapshot == null) {
        return sequenceRanges;
    }

    String snapshotText = snapshot.getText();
    List<String> splitText = Arrays.asList(snapshotText.split(" "));
    int snapshotLength = splitText.size();

    for (int i = 0; i < snapshotLength; i++) {
        String word = splitText.get(i);
        int startIndex = snapshotText.indexOf(word);
        int endIndex = startIndex + word.length() - 1;
        boolean isDiscrete = false;
        if (i == 0 || i == snapshotLength - 1) {
            isDiscrete = true;
        }
        sequenceRanges.add(new SequenceRange(startIndex, endIndex, isDiscrete));
    }

    return sequenceRanges;
}

