    }
    int lastSeparatorIndex = path.lastIndexOf(File.separatorChar) + 1;
    int lastExtensionIndex = path.lastIndexOf('.');
    if(lastExtensionIndex == -1 || lastExtensionIndex < lastSeparatorIndex){
        return path;
    }
    return path.substring(0, lastExtensionIndex);
}

public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int filenamePos = path.lastIndexOf('/');
    if (filenamePos == -1) {
        return null;
    }
    int extensionPos = path.lastIndexOf('.');
    if (extensionPos == -1 || extensionPos < filenamePos) {
        return path;
    }
    return path.substring(0, extensionPos);
}

