private String parseToken(final char[] terminators) {
    StringBuilder token = new StringBuilder();
    while (hasNext()) {
        char c = next();
        if (Arrays.binarySearch(terminators, c) >= 0) {
            break;
        }
        token.append(c);
    }
    return token.toString();
}

private String parseToken(final char[] terminators) {
    StringBuilder token = new StringBuilder();
    char c = readChar();
    while (!isTerminator(c, terminators)) {
        token.append(c);
        c = readChar();
    }
    return token.toString();
}

private String parseToken(final char[] terminators){
    /*
    Parses out a token until any of the given terminators is encountered.
    :param terminators: the array of terminating characters. Any of these characters when encountered signify the end of the token.
    :return: the token
    */

class Tokenizer {
    private:
        std::string text;
        std::vector<char> terminators;
        int cursor;
        int end;

    public:
        Tokenizer(const std::string& text, const std::vector<char> terminators): text(text), terminators(terminators), cursor(0), end(text.size()) {}

        std::string parseToken() {
            std::string token;
            while (cursor < end && !std::find(terminators.begin(), terminators.end(), text[cursor])) {
                token += text[cursor++];
            }
            return token;
        }
}

