private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSums = new ArrayList<Integer>();
    long sum = 0;
    for (int i = 0; i < bounds.size(); i++) {
        sum += bounds.get(i);
        suffixSums.add(sum);
    }
    return new Pair<List<Integer>,Long>(suffixSums, sum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    long sum = 0L;
    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add(i, (int) sum);
    }
    return new Pair<>(suffixSum, sum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;
    for (int i = 0; i < bounds.size(); i++) {
        suffixSum.add(totalSum + bounds.get(i));
        totalSum += bounds.get(i);
    }
    return Pair.of(suffixSum, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return null;
    }
    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        int sum = 0;
        for (int j = i; j < n; j++) {
            sum += bounds.get(j);
        }
        suffixSum.add(sum);
    }
    long sumOfAllElements = suffixSum.stream().mapToLong(Integer::intValue).sum();
    return Pair.of(suffixSum, sumOfAllElements);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add(0, sum);
    }
    return Pair.of(suffixSum, sum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    int left = from;
    int right = to;
    while (left < right) {
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

public static final <V>void reverse(V[] arr, int from, int to) {
    // Check if the range is valid
    if (from < 0 || from > arr.length || to < 0 || to > arr.length) {
        throw new IndexOutOfBoundsException("Invalid range: (from=" + from + ", to=" + to + ")");
    }

    // Reverse the elements in the range
    for (int i = from; i < to; i++) {
        int mirrorIndex = (to - from - 1) - i;
        V temp = arr[i];
        arr[i] = arr[mirrorIndex];
        arr[mirrorIndex] = temp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    int length = to - from + 1;
    for (int i = 0; i < length / 2; i++) {
        V temp = arr[from + i];
        arr[from + i] = arr[to - i];
        arr[to - i] = temp;
    }
}

public static <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0 || from >= to) {
        return;
    }
    int mid = (from + to) / 2;
    for (int i = from; i < mid; i++) {
        V temp = arr[i];
        arr[i] = arr[to - i + from];
        arr[to - i + from] = temp;
    }
}

public static <V> void reverse(V[] arr, int from, int to) {
    int len = to - from + 1;
    for (int i = 0; i < len / 2; i++) {
        int j = len - i - 1;
        V temp = arr[from + i];
        arr[from + i] = arr[from + j];
        arr[from + j] = temp;
    }
}

