private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given subgraph is a clique
    for (int i = 0; i < vertices.size(); i++) {
        for (int j = i + 1; j < vertices.size(); j++) {
            if (!graph.containsEdge(vertices.get(i), vertices.get(j))) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph has at least one edge
    if (graph.getEdges().isEmpty()) {
        return false;
    }

    // Check if the vertices have at least one edge between them
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.hasEdge(v1, v2)) {
                return false;
            }
        }
    }

    // Check if the induced subgraph is complete
    for (E edge : graph.getEdges()) {
        V v1 = edge.getV1();
        V v2 = edge.getV2();
        if (!vertices.contains(v1) || !vertices.contains(v2)) {
            return false;
        }
    }

    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.size() == 0) {
        return true;
    }
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            return false;
        }
        for (V neighbor : graph.getNeighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true;
    }
    V v = vertices.iterator().next();
    for (V u : vertices) {
        if (!graph.getNeighbors(u).contains(v)) {
            return false;
        }
    }
    return true;
}

