public static String applyRelativePath(String path, String relativePath) {
    // Convert the relative path to a list of path components
    List<String> relativeComponents = Arrays.asList(relativePath.split("/"));

    // Initialize the stack to hold the path components
    Stack<String> stack = new Stack<>();

    // Push each path component onto the stack
    for (String component : relativeComponents) {
        stack.push(component);
    }

    // Loop through the path components, resolving ".." and "." components
    while (!stack.isEmpty()) {
        String component = stack.pop();

        if (component.equals("..")) {
            // ".." means to go up one directory
            stack.pop();
        } else if (component.equals(".")) {
            // "." means to stay in the current directory
        } else {
            // Push the component onto the stack
            stack.push(component);
        }
    }

    // Join the path components together, separated by "/"
    StringBuilder builder = new StringBuilder();
    for (String component : stack) {
        builder.append("/").append(component);
    }

    // Return the full file path
    return builder.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    // Assume that the path and relativePath are valid
    // Strip any leading or trailing separators from the path and relativePath
    path = path.stripLeadingSeparators().stripTrailingSeparators();
    relativePath = relativePath.stripLeadingSeparators().stripTrailingSeparators();

    // Split the path and relativePath into lists of folder names
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Iterate over the relativePathParts and update the pathParts accordingly
    for (String part : relativePathParts) {
        if (part.equals(".")) {
            // Do nothing
        } else if (part.equals("..")) {
            pathParts.pop();
        } else {
            part.push(pathParts);
        }
    }

    // Join the pathParts back together to form the full file path
    return pathParts.join("/") + "/" + relativePathParts.join("/");
}

public static String applyRelativePath(String path, String relativePath) {
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");
    for (int i = 0; i < relativePathParts.length; i++) {
        if (relativePathParts[i].equals(".")) {
            // Do nothing
        } else if (relativePathParts[i].equals("..")) {
            if (pathParts.length > 1) {
                pathParts = Arrays.copyOf(pathParts, pathParts.length - 1);
            }
        } else {
            pathParts = Arrays.copyOf(pathParts, pathParts.length + 1);
            pathParts[pathParts.length - 1] = relativePathParts[i];
        }
    }
    return String.join("/", pathParts);
}

public static String applyRelativePath(String path, String relativePath) {
    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");
    for (int i = 0; i < relativeParts.length; i++) {
        if (relativeParts[i].equals("..")) {
            pathParts = pathParts.length > 1 ? pathParts[0..pathParts.length - 2] : "/";
        } else {
            pathParts = pathParts.length > 0 ? pathParts.concat(relativeParts[i]) : relativeParts[i];
        }
    }
    return pathParts.length > 0 ? pathParts[0] + "/" + pathParts.join("/") : path;
}

