public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line = reader.readLine().trim();
        while (line != null) {
            if (line.startsWith("[")) {
                line = line.substring(1, line.length() - 1);
                line = line.trim();
                if (line.isEmpty()) {
                    break;
                }
                String[] parts = line.split(" ");
                long threadId = Long.parseLong(parts[0]);
                long threadState = Long.parseLong(parts[1]);
                long threadWaitStartTime = Long.parseLong(parts[2]);
                long threadWaitEndTime = Long.parseLong(parts[3]);
                long threadWaitTime = threadWaitEndTime - threadWaitStartTime;
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, threadState, threadWaitTime);
                threadSnapshots.add(threadSnapshot);
            }
            line = reader.readLine();
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line = reader.readLine();
        while (line != null) {
            ThreadSnapshot threadSnapshot = ThreadSnapshot.parseFromLine(line);
            if (threadSnapshot != null && isSnapshotInTimeRange(threadSnapshot, timeRanges)) {
                threadSnapshots.add(threadSnapshot);
            }
            line = reader.readLine();
        }
    }
    return threadSnapshots;
}

private static boolean isSnapshotInTimeRange(ThreadSnapshot snapshot, List<ProfileAnalyzeTimeRange> timeRanges) {
    long startTime = snapshot.getStartTime();
    long endTime = snapshot.getEndTime();
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (startTime >= timeRange.getStartTime() && endTime <= timeRange.getEndTime()) {
            return true;
        }
    }
    return false;
}
